{
  "name": "并行任务队列",
  "name_en": "Parallel Task Queue",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于实验相关的并行计算与数据处理流程。它负责向工作进程分发任务、接收已完成结果、归档结果，并统计开放、进行中和已完成的任务数量。",
  "description_en": "This is a non-physical software component used in experiment-related parallel computation and data-processing workflows. It distributes tasks to workers, receives completed results, files results, and tracks open, in-progress, and completed task counts.",
  "actions": [
    {
      "action_name": "auto-postTask",
      "description": "向队列提交单个任务。",
      "description_en": "Submit a single task to the queue."
    },
    {
      "action_name": "auto-postTasks",
      "description": "向队列批量提交多个任务。",
      "description_en": "Submit multiple tasks to the queue."
    },
    {
      "action_name": "auto-getTask",
      "description": "为工作进程获取一个待处理任务。",
      "description_en": "Retrieve one pending task for a worker."
    },
    {
      "action_name": "auto-getTasks",
      "description": "为工作进程获取一批待处理任务。",
      "description_en": "Retrieve a batch of pending tasks for a worker."
    },
    {
      "action_name": "auto-returnCompletedTask",
      "description": "提交单个已完成任务的结果。",
      "description_en": "Return the result of one completed task."
    },
    {
      "action_name": "auto-returnCompletedTasks",
      "description": "批量提交多个已完成任务的结果。",
      "description_en": "Return the results of multiple completed tasks."
    },
    {
      "action_name": "auto-fileResults",
      "description": "归档一批任务结果。",
      "description_en": "File a batch of task results."
    },
    {
      "action_name": "auto-fileResult",
      "description": "归档单个任务结果。",
      "description_en": "File a single task result."
    },
    {
      "action_name": "auto-getCompletedTask",
      "description": "获取一个已完成任务的结果。",
      "description_en": "Get one completed task result."
    },
    {
      "action_name": "auto-checkTimeouts",
      "description": "检查并处理超时任务。",
      "description_en": "Check for and handle timed-out tasks."
    },
    {
      "action_name": "auto-getNumberOpenTasks",
      "description": "获取当前开放任务数量。",
      "description_en": "Get the current number of open tasks."
    },
    {
      "action_name": "auto-getNumberTasksInProgress",
      "description": "获取当前进行中任务数量。",
      "description_en": "Get the current number of tasks in progress."
    },
    {
      "action_name": "auto-getNumberTasksCompleted",
      "description": "获取当前已完成任务数量。",
      "description_en": "Get the current number of completed tasks."
    },
    {
      "action_name": "auto-cleanup",
      "description": "清理队列相关资源和状态。",
      "description_en": "Clean up queue-related resources and state."
    },
    {
      "action_name": "auto-purge",
      "description": "清空队列中的任务和结果。",
      "description_en": "Purge tasks and results from the queue."
    },
    {
      "action_name": "auto-setPopFcn",
      "description": "设置任务弹出或分配策略函数。",
      "description_en": "Set the task pop or dispatch selection function."
    }
  ],
  "tag_hints": [
    "task scheduling",
    "parallel processing",
    "worker queue",
    "result collection",
    "distributed computation",
    "experiment workflow"
  ]
}

